script:
set -eu
node <<'NODE'
const fs=require('fs'),crypto=require('crypto');
const files=['/app/node_modules/next/dist/compiled/picomatch/index.js','/app/node_modules/next/dist/compiled/picomatch/package.json','/app/node_modules/next/dist/server/app-render/csrf-protection.js','/app/node_modules/react/cjs/react.development.js'];
const results=files.map(p=>{const b=fs.readFileSync(p),s=b.toString('utf8');let occurrences=[];for(const needle of ['braces','micromatch','fast-glob','require("braces")',"require('braces')",'ast.nodes','braces.parse','braces.compile','braces.expand']){let i=s.indexOf(needle),count=0;while(i>=0&&count++<6){occurrences.push({needle,offset:i,context:s.slice(Math.max(0,i-100),i+needle.length+160)});i=s.indexOf(needle,i+needle.length)}}return {path:p,bytes:b.length,sha256:crypto.createHash('sha256').update(b).digest('hex'),occurrences,packageJson:p.endsWith('package.json')?JSON.parse(s):undefined}});
console.log(JSON.stringify(results,null,2));
